import React, { useState } from 'react';
import Questionnaire from '../components/Questionnaire';
import MovieCard from '../components/MovieCard';

const Home = () => {
    // Yapay zekadan dönecek olan film önerilerini tutacağımız State (Artık bir dizi tutacak)
    const [recommendations, setRecommendations] = useState(null);

    return (
        <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'sans-serif' }}>
            <h1 style={{ textAlign: 'center', color: '#2c3e50' }}>🎬 CineSense AI Motoru</h1>
            <p style={{ textAlign: 'center', color: '#7f8c8d', marginBottom: '30px' }}>
                Ruh halini seç, yapay zeka senin için en mükemmel filmleri bulsun.
            </p>

            {/* Anket bileşenini çağırıyoruz ve sonucu yakalıyoruz */}
            <Questionnaire onRecommendationReceived={(data) => setRecommendations(data)} />

            {/* Eğer recommendations state'i dolduysa ve içinde veri varsa haritalayıp (map) ekrana basıyoruz */}
            {recommendations && recommendations.length > 0 && (
                <div style={{ marginTop: '50px' }}>
                    <h2 style={{ textAlign: 'center', color: '#27ae60', marginBottom: '30px' }}>
                        ✨ Yapay Zekanın Senin İçin Seçtiği İlk 5 Film ✨
                    </h2>

                    {/* Gelen 5 filmi döngüye sokup her biri için bir MovieCard oluşturuyoruz */}
                    {recommendations.map((movie) => (
                        <MovieCard key={movie.id} movie={movie} />
                    ))}
                </div>
            )}
        </div>
    );
};

export default Home;
